
import { prefs, bus } from './principal.js';

const LANGS = [
  { code: 'pt-BR', name: 'Português (BR)' },
  { code: 'en', name: 'English' },
  { code: 'es', name: 'Español' },
  { code: 'fr', name: 'Français' },
  { code: 'de', name: 'Deutsch' },
  { code: 'it', name: 'Italiano' },
  { code: 'ja', name: '日本語' },
  { code: 'zh-CN', name: '简体中文' },
  { code: 'ko', name: '한국어' },
  { code: 'ru', name: 'Русский' },
  { code: 'ar', name: 'العربية', dir: 'rtl' },
  { code: 'hi', name: 'हिन्दी' },
];
const BASE = 'pt-BR';
const ATTRS = ['aria-label', 'placeholder', 'alt', 'title'];
const SKIP = 'script, style, noscript, canvas, svg, code, .material-symbols-outlined, [data-no-i18n], [data-hero-title], .model-slot__path';

const norm = (s) => s.replace(/\s+/g, ' ').trim();
let lang = BASE, dict = null;
const textOrig = new WeakMap(), textSet = new WeakMap();   // nó de texto → original / último valor escrito por nós
const attrOrig = new WeakMap(), attrSet = new WeakMap();   // elemento → { atributo: original / escrito }
let titleOrig = null;
const seen = null;

/** Traduz uma frase (para textos que não estão no DOM). */
function t(s) { const k = norm(s); seen?.add(k); return (dict && dict[k]) || s; }
const currentLang = () => lang;

function tr(raw) {
  const k = norm(raw);
  if (!k || !/\p{L}/u.test(k)) return raw;
  seen?.add(k);
  const v = dict?.[k];
  if (!v) return raw;
  const lead = raw.match(/^\s*/)[0], trail = raw.match(/\s*$/)[0];
  return lead + v + trail;
}

function doText(n) {
  if (textSet.get(n) === n.nodeValue) return;           // fomos nós que escrevemos
  textOrig.set(n, n.nodeValue);                           // texto novo (original em português)
  const v = lang === BASE ? n.nodeValue : tr(n.nodeValue);
  textSet.set(n, v);
  if (v !== n.nodeValue) n.nodeValue = v;
}

function doAttrs(el) {
  for (const a of ATTRS) {
    if (!el.hasAttribute(a)) continue;
    const cur = el.getAttribute(a), set = attrSet.get(el) ?? {}, orig = attrOrig.get(el) ?? {};
    if (set[a] === cur) continue;
    orig[a] = cur;
    const v = lang === BASE ? cur : tr(cur);
    set[a] = v; attrOrig.set(el, orig); attrSet.set(el, set);
    if (v !== cur) el.setAttribute(a, v);
  }
}

function walk(root) {
  if (root.nodeType === 3) { if (!root.parentElement?.closest(SKIP)) doText(root); return; }
  if (root.nodeType !== 1 || root.closest?.(SKIP)) return;
  doAttrs(root);
  const it = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => (n.nodeType === 1 && n.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
  });
  for (let n = it.nextNode(); n; n = it.nextNode()) { if (n.nodeType === 3) doText(n); else doAttrs(n); }
}

/** Reaplica o idioma atual a tudo (usando sempre o português original como fonte). */
function reapply() {
  const it = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => (n.nodeType === 1 && n.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
  });
  for (let n = it.nextNode(); n; n = it.nextNode()) {
    if (n.nodeType === 3) {
      if (n.parentElement?.closest(SKIP)) continue;
      const o = textSet.get(n) === n.nodeValue ? textOrig.get(n) : n.nodeValue;
      textOrig.set(n, o);
      const v = lang === BASE ? o : tr(o);
      textSet.set(n, v); if (v !== n.nodeValue) n.nodeValue = v;
    } else {
      const set = attrSet.get(n) ?? {}, orig = attrOrig.get(n) ?? {};
      for (const a of ATTRS) {
        if (!n.hasAttribute(a)) continue;
        const cur = n.getAttribute(a), o = set[a] === cur ? orig[a] : cur;
        orig[a] = o; const v = lang === BASE ? o : tr(o); set[a] = v;
        if (v !== cur) n.setAttribute(a, v);
      }
      attrOrig.set(n, orig); attrSet.set(n, set);
    }
  }
  titleOrig ??= document.title;
  document.title = lang === BASE ? titleOrig : tr(titleOrig);
}

/** Idioma pelo navegador (primeira visita). */
function detectLang() {
  for (const l of navigator.languages ?? [navigator.language]) {
    const low = (l || '').toLowerCase();
    const exact = LANGS.find((x) => x.code.toLowerCase() === low);
    if (exact) return exact.code;
    const base = low.split('-')[0];
    if (base === 'pt') return 'pt-BR'; // todas as variantes do português usam o pt-BR
    if (base === 'zh') return 'zh-CN';
    const b = LANGS.find((x) => x.code.toLowerCase() === base);
    if (b) return b.code;
  }
  return BASE;
}

/** Troca o idioma na hora (sem recarregar). */
async function setLang(code) {
  const info = LANGS.find((l) => l.code === code) ?? LANGS[0];
  if (info.code !== BASE) {
    dict = DICIONARIOS[info.code] ?? null; // os dicionários ficam no fim deste arquivo
  } else dict = null;
  lang = info.code;
  const root = document.documentElement;
  root.lang = info.code; root.dir = info.dir ?? 'ltr';
  reapply();
  prefs.set('lang', info.code);
  bus.emit('lang', info.code);
  return info.code;
}

/** Liga a tradução automática (inclusive do que o JavaScript criar depois) e aplica o idioma salvo/detectado. */
async function initI18n() {
  const mo = new MutationObserver((list) => {
    for (const m of list) {
      if (m.type === 'childList') m.addedNodes.forEach((n) => walk(n));
      else if (m.type === 'characterData') { if (!m.target.parentElement?.closest(SKIP)) doText(m.target); }
      else if (m.type === 'attributes' && !m.target.closest(SKIP)) doAttrs(m.target);
    }
  });
  mo.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRS });
  if (seen) {
    // (dev) lista as frases originais em português visíveis agora — usada para manter os dicionários completos
    window.__i18nCollect = () => {
      const out = new Set(seen);
      const it = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
        acceptNode: (n) => (n.nodeType === 1 && n.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
      });
      for (let n = it.nextNode(); n; n = it.nextNode()) {
        if (n.nodeType === 3) { if (!n.parentElement?.closest(SKIP)) out.add(norm(textOrig.get(n) ?? n.nodeValue)); }
        else for (const a of ATTRS) if (n.hasAttribute(a)) out.add(norm(attrOrig.get(n)?.[a] ?? n.getAttribute(a)));
      }
      out.add(norm(titleOrig ?? document.title));
      return [...out].filter((k) => /\p{L}/u.test(k));
    };
  }
  const saved = prefs.get('lang');
  await setLang(saved && LANGS.some((l) => l.code === saved) ? saved : detectLang());
}

