  "Desenvolvimento, Inovação & Defesa Cibernética": "Development, Innovation & Cyber Defense",
  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "My path is driven by curiosity and a passion for technology and books. Since I was a kid, I have explored my creativity by making Minecraft mods, designing characters and turning my own ideas into reality, whether through technology or by writing books. I have always sought to learn Java and other languages, and I am always looking to learn something new.",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "I have web development skills, building modern, responsive interfaces with HTML, CSS, JavaScript and Bootstrap. I have also been exploring 3D modeling and development, using tools such as Blender, Blockbench and Unity to create characters, environments and three-dimensional experiences in my projects.",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "I have also been going deeper into cybersecurity, studying vulnerability analysis, networking, pentesting and digital protection best practices. I use Python, Java and C# for projects and automation, exploring different ways to solve problems through programming. I have invested heavily in courses, certifications and hands-on projects, which has given me a solid foundation in technology, information security and artificial intelligence.",
