  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "Mi trayectoria está guiada por la curiosidad y la pasión por la tecnología y los libros. Desde pequeño me gusta explorar mi creatividad creando mods para Minecraft, desarrollando personajes y haciendo realidad mis propias ideas, ya sea con la tecnología o escribiendo libros. Siempre he buscado aprender Java y otros lenguajes, y siempre estoy buscando aprender algo nuevo.",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "Tengo conocimientos de desarrollo web y creo interfaces modernas y responsivas con HTML, CSS, JavaScript y Bootstrap. También estoy explorando el modelado y el desarrollo 3D, con herramientas como Blender, Blockbench y Unity, para crear personajes, entornos y experiencias tridimensionales en mis proyectos.",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "Además, me estoy especializando en ciberseguridad, estudiando análisis de vulnerabilidades, redes, pentest y buenas prácticas de protección digital. También uso Python, Java y C# en proyectos y automatización, explorando distintas formas de resolver problemas con la programación. He invertido mucho en cursos, certificaciones y proyectos prácticos, lo que me ha permitido construir una base sólida en tecnología, seguridad de la información e inteligencia artificial.",
