  "Rede Social Acadêmica em Tempo Real": "Réseau social académique en temps réel",
  "Ecossistema acadêmico completo voltado para mentoria e troca de conhecimento entre estudantes e instrutores. Conta com comunicação bi-direcional em tempo real via WebSocket STOMP, autenticação robusta OAuth2 e gamificação de aprendizado.": "Écosystème académique complet dédié au mentorat et au partage de connaissances entre étudiants et formateurs. Il propose une communication bidirectionnelle en temps réel via WebSocket STOMP, une authentification OAuth2 robuste et la gamification de l'apprentissage.",
  "Chat e sessões colaborativas de mentoria em tempo real via WebSocket e mensageria STOMP.": "Chat et sessions collaboratives de mentorat en temps réel via WebSocket et la messagerie STOMP.",
  "Mecanismo de controle de acesso rigoroso com Spring Security, criptografia BCrypt e tokens.": "Contrôle d'accès rigoureux avec Spring Security, chiffrement BCrypt et jetons.",
  "Gamificação dinâmica com acúmulo de pontos de transmissão, badges de conquista e ranking.": "Gamification dynamique avec cumul de points de partage, badges de réussite et classement.",
  "Exploração Anatômica & Modelagem 3D": "Exploration anatomique & modélisation 3D",
  "Renderização tridimensional em tempo real via WebGL com controle de câmeras e corte transversal.": "Rendu 3D en temps réel via WebGL avec contrôle des caméras et coupes transversales.",
  "Sistema de anotações médicas holográficas e nós de descrição histológica interativos.": "Annotations médicales holographiques et nœuds interactifs de description histologique.",
  "Alta performance gráfica computacional com pipeline de shaders customizados GLSL.": "Hautes performances graphiques grâce à un pipeline de shaders GLSL personnalisés.",
  "Modding Criativo & Engenharia Virtual": "Modding créatif & ingénierie virtuelle",
  "Universo fantástico inspirado no cânone de Oz, transportando elementos icônicos como a Cidade das Esmeraldas e a Estrada de Tijolos Amarelos para mecânicas interativas com engenharia de software criativa e customização profunda.": "Univers fantastique inspiré du canon d'Oz, qui transpose des éléments emblématiques comme la Cité d'Émeraude et la Route de briques jaunes en mécaniques interactives grâce à une ingénierie logicielle créative et une personnalisation poussée.",
  "Geração procedural de estruturas e biomas mágicos inspirados na Cidade das Esmeraldas.": "Génération procédurale de structures et de biomes magiques inspirés de la Cité d'Émeraude.",
  "Sistema de itens mágicos, poções alquímicas e mecânicas customizadas com alta taxa de quadros.": "Objets magiques, potions alchimiques et mécaniques personnalisées avec une fréquence d'images élevée.",
  "Arquitetura modular orientada a eventos para integração contínua de novos assets e feitiços.": "Architecture modulaire orientée événements pour intégrer en continu de nouveaux assets et sorts.",
  "Plataforma Analítica & Gestão": "Plateforme d'analyse & de gestion",
  "Rastreamento de ativos e movimentações de carga em tempo real com auditoria de logs.": "Suivi en temps réel des actifs et des mouvements de marchandises avec audit des journaux.",
  "Geração de relatórios preditivos de demanda e esgotamento de suprimentos.": "Rapports prédictifs sur la demande et les ruptures d'approvisionnement.",
  "Camada de persistência relacional ultra veloz com SQLite e ORM Django otimizado.": "Couche de persistance relationnelle ultra-rapide avec SQLite et un ORM Django optimisé.",
  // ---- etapa 6: Sobre Mim, Currículo e Contato ----
  "Sobre Mim": "À propos de moi",
  "MINHA VISÃO E PROTOCOLOS": "MA VISION & MES PROTOCOLES",
  "Desenvolvimento, Inovação & Defesa Cibernética": "Développement, innovation & cyberdéfense",
  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "Mon parcours est guidé par la curiosité et la passion pour la technologie et les livres. Depuis tout petit, j'aime explorer ma créativité en créant des mods pour Minecraft, en concevant des personnages et en donnant vie à mes propres idées, que ce soit par la technologie ou par l'écriture de livres. J'ai toujours cherché à apprendre Java et d'autres langages, et je cherche toujours à apprendre quelque chose de nouveau.",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "J'ai des compétences en développement web et je crée des interfaces modernes et responsives avec HTML, CSS, JavaScript et Bootstrap. J'explore aussi la modélisation et le développement 3D, avec des outils comme Blender, Blockbench et Unity, pour créer des personnages, des environnements et des expériences en trois dimensions dans mes projets.",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "Je m'approfondis également en cybersécurité : analyse de vulnérabilités, réseaux, pentest et bonnes pratiques de protection numérique. J'utilise aussi Python, Java et C# pour mes projets et l'automatisation, en explorant différentes façons de résoudre des problèmes par la programmation. J'ai beaucoup investi dans des formations, des certifications et des projets pratiques, ce qui m'a permis de bâtir une base solide en technologie, en sécurité de l'information et en intelligence artificielle.",
  "COMPETÊNCIAS TÉCNICAS // TECH STACK HUD": "COMPÉTENCES TECHNIQUES // TECH STACK HUD",
  "DESENVOLVIMENTO BACK-END & APIs": "DÉVELOPPEMENT BACK-END & APIs",
