  "Imersão prática em arquitetura de computadores, redes de comunicação, lógica de programação, desenvolvimento de software e aplicações web, estruturas de dados, bancos de dados relacionais, modelagem de sistemas e segurança da informação.": "Immersion pratique en architecture des ordinateurs, réseaux de communication, logique de programmation, développement de logiciels et d'applications web, structures de données, bases de données relationnelles, modélisation de systèmes et sécurité de l'information.",
  "EXPERIÊNCIA PRÁTICA & EXPERIÊNCIA TÉCNICA": "EXPÉRIENCE PRATIQUE & TECHNIQUE",
