  // ---- etapa 6: Sobre Mim, Currículo e Contato ----
  "Sobre Mim": "Über mich",
  "MINHA VISÃO E PROTOCOLOS": "MEINE VISION & PROTOKOLLE",
  "Desenvolvimento, Inovação & Defesa Cibernética": "Entwicklung, Innovation & Cyberabwehr",
  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "Mein Weg wird von Neugier und meiner Leidenschaft für Technologie und Bücher geleitet. Schon als Kind lebe ich meine Kreativität aus, indem ich Mods für Minecraft erstelle, Figuren entwickle und meine eigenen Ideen Wirklichkeit werden lasse – ob mit Technologie oder beim Schreiben von Büchern. Ich wollte schon immer Java und andere Sprachen lernen und suche ständig nach etwas Neuem.",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "Ich habe Kenntnisse in der Webentwicklung und gestalte moderne, responsive Oberflächen mit HTML, CSS, JavaScript und Bootstrap. Außerdem beschäftige ich mich mit 3D-Modellierung und -Entwicklung und nutze Tools wie Blender, Blockbench und Unity, um Figuren, Umgebungen und dreidimensionale Erlebnisse für meine Projekte zu erschaffen.",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "Darüber hinaus vertiefe ich mich in Cybersicherheit und beschäftige mich mit Schwachstellenanalyse, Netzwerken, Pentesting und Best Practices für digitalen Schutz. Für Projekte und Automatisierung nutze ich Python, Java und C# und erkunde verschiedene Wege, Probleme durch Programmierung zu lösen. Ich habe viel in Kurse, Zertifizierungen und praktische Projekte investiert und mir so eine solide Grundlage in Technologie, Informationssicherheit und künstlicher Intelligenz aufgebaut.",
  "COMPETÊNCIAS TÉCNICAS // TECH STACK HUD": "TECHNISCHE KOMPETENZEN // TECH STACK HUD",
  "DESENVOLVIMENTO BACK-END & APIs": "BACKEND-ENTWICKLUNG & APIs",
