  "Desenvolvimento, Inovação & Defesa Cibernética": "Sviluppo, innovazione e difesa informatica",
  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "Il mio percorso è guidato dalla curiosità e dalla passione per la tecnologia e i libri. Fin da piccolo mi piace esplorare la mia creatività creando mod per Minecraft, sviluppando personaggi e trasformando le mie idee in realtà, sia con la tecnologia sia scrivendo libri. Ho sempre cercato di imparare Java e altri linguaggi e sono sempre alla ricerca di qualcosa di nuovo da imparare.",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "Ho competenze di sviluppo web e realizzo interfacce moderne e responsive con HTML, CSS, JavaScript e Bootstrap. Sto anche esplorando la modellazione e lo sviluppo 3D, con strumenti come Blender, Blockbench e Unity, per creare personaggi, ambienti ed esperienze tridimensionali nei miei progetti.",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "Inoltre sto approfondendo la cybersicurezza, studiando analisi delle vulnerabilità, reti, pentest e buone pratiche di protezione digitale. Uso anche Python, Java e C# per progetti e automazione, esplorando modi diversi di risolvere problemi con la programmazione. Ho investito molto in corsi, certificazioni e progetti pratici, che mi hanno permesso di costruire una solida base in tecnologia, sicurezza delle informazioni e intelligenza artificiale.",
