  "Rede Social Acadêmica em Tempo Real": "リアルタイム学術SNS",
  "Ecossistema acadêmico completo voltado para mentoria e troca de conhecimento entre estudantes e instrutores. Conta com comunicação bi-direcional em tempo real via WebSocket STOMP, autenticação robusta OAuth2 e gamificação de aprendizado.": "学生と講師のメンタリングと知識共有のための総合的な学術エコシステム。WebSocket STOMPによるリアルタイムの双方向通信、堅牢なOAuth2認証、学習のゲーミフィケーションを備えています。",
  "Chat e sessões colaborativas de mentoria em tempo real via WebSocket e mensageria STOMP.": "WebSocketとSTOMPメッセージングによるリアルタイムのチャットと共同メンタリングセッション。",
