  "Modding Criativo & Engenharia Virtual": "クリエイティブなMOD制作とバーチャルエンジニアリング",
  "Universo fantástico inspirado no cânone de Oz, transportando elementos icônicos como a Cidade das Esmeraldas e a Estrada de Tijolos Amarelos para mecânicas interativas com engenharia de software criativa e customização profunda.": "オズの世界観に着想を得たファンタジー世界。エメラルドの都や黄色いレンガの道といった象徴的な要素を、創造的なソフトウェアエンジニアリングと深いカスタマイズによってインタラクティブな仕組みに落とし込みました。",
  "Geração procedural de estruturas e biomas mágicos inspirados na Cidade das Esmeraldas.": "エメラルドの都に着想を得た魔法の建造物とバイオームのプロシージャル生成。",
  "Sistema de itens mágicos, poções alquímicas e mecânicas customizadas com alta taxa de quadros.": "魔法アイテム、錬金術のポーション、高フレームレートで動くカスタムメカニクス。",
  "Arquitetura modular orientada a eventos para integração contínua de novos assets e feitiços.": "新しいアセットや呪文を継続的に追加できる、イベント駆動のモジュール型アーキテクチャ。",
