  "Sobre Mim": "自己紹介",
  "MINHA VISÃO E PROTOCOLOS": "私のビジョンとプロトコル",
  "Desenvolvimento, Inovação & Defesa Cibernética": "開発・イノベーション・サイバー防御",
  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "私の歩みは、好奇心とテクノロジー・本への情熱に導かれています。幼い頃からMinecraftのMOD制作を通じて創造力を発揮し、キャラクターを作り、自分のアイデアをテクノロジーや本の執筆という形で実現してきました。Javaをはじめとする言語を常に学び続け、いつも新しいことを学ぼうとしています。",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "Web開発の知識があり、HTML、CSS、JavaScript、Bootstrapでモダンかつレスポンシブなインターフェースを制作しています。また、Blender、Blockbench、Unityなどのツールを使った3Dモデリングと開発にも取り組み、プロジェクトでキャラクターや環境、立体的な体験を作っています。",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "さらに、脆弱性分析、ネットワーク、ペネトレーションテスト、デジタル保護のベストプラクティスを学び、サイバーセキュリティの分野を深めています。Python、Java、C#をプロジェクトや自動化に活用し、プログラミングでさまざまな課題解決の方法を探っています。講座、資格、実践的なプロジェクトに力を注ぎ、テクノロジー、情報セキュリティ、人工知能の確かな基礎を築いてきました。",
  "COMPETÊNCIAS TÉCNICAS // TECH STACK HUD": "技術スキル // TECH STACK HUD",
