  "Engenharia de Software de Alta Precisão & Defesa Cibernética": "هندسة برمجيات عالية الدقة ودفاع سيبراني",
  "Minha trajetória é guiada pela curiosidade técnica incansável e pela paixão por construir sistemas que combinam arquitetura robusta, performance extrema e segurança de ponta a ponta. Seja projetando ecossistemas corporativos escaláveis em Java e Spring Boot ou criando interfaces cinematográficas em 3D, meu foco é a entrega de valor com integridade inabalável.": "تقودني مسيرتي بفضول تقني لا يهدأ وشغف ببناء أنظمة تجمع بين البنية المتينة والأداء الفائق والأمان الشامل. سواء كنت أصمم منظومات مؤسسية قابلة للتوسع باستخدام Java وSpring Boot أو أبتكر واجهات ثلاثية الأبعاد سينمائية، فإن تركيزي هو تقديم قيمة حقيقية بنزاهة لا تتزعزع.",
  "Combinando formação em Ciência da Computação com certificações ativas em testes de intrusão e resposta a incidentes, aplico uma mentalidade 'Security by Design' em cada linha de código commitada.": "بجمعي بين خلفية في علوم الحاسوب وشهادات سارية في اختبار الاختراق والاستجابة للحوادث، أطبّق عقلية «الأمان منذ التصميم» في كل سطر برمجي أعتمده.",
