  "Ecossistema acadêmico completo voltado para mentoria e troca de conhecimento entre estudantes e instrutores. Conta com comunicação bi-direcional em tempo real via WebSocket STOMP, autenticação robusta OAuth2 e gamificação de aprendizado.": "منظومة أكاديمية متكاملة للإرشاد وتبادل المعرفة بين الطلاب والمدرّبين. تتضمن تواصلًا ثنائي الاتجاه في الوقت الفعلي عبر WebSocket STOMP، ومصادقة قوية عبر OAuth2، وتلعيب التعلّم.",
  "Chat e sessões colaborativas de mentoria em tempo real via WebSocket e mensageria STOMP.": "دردشة وجلسات إرشاد تعاونية في الوقت الفعلي عبر WebSocket ومراسلة STOMP.",
  "Mecanismo de controle de acesso rigoroso com Spring Security, criptografia BCrypt e tokens.": "تحكم صارم في الوصول باستخدام Spring Security وتشفير BCrypt والرموز المميزة.",
