  "Renderização tridimensional em tempo real via WebGL com controle de câmeras e corte transversal.": "عرض ثلاثي الأبعاد في الوقت الفعلي عبر WebGL مع التحكم في الكاميرات والمقاطع العرضية.",
  "Sistema de anotações médicas holográficas e nós de descrição histológica interativos.": "نظام تعليقات طبية هولوغرافية وعُقد تفاعلية لوصف الأنسجة.",
  "Alta performance gráfica computacional com pipeline de shaders customizados GLSL.": "أداء رسومي عالٍ بفضل مسار معالجة مخصص لمظلّلات GLSL.",
  "Modding Criativo & Engenharia Virtual": "تعديل إبداعي وهندسة افتراضية",
  "Universo fantástico inspirado no cânone de Oz, transportando elementos icônicos como a Cidade das Esmeraldas e a Estrada de Tijolos Amarelos para mecânicas interativas com engenharia de software criativa e customização profunda.": "عالم خيالي مستوحى من قصص أوز، ينقل عناصر أيقونية مثل مدينة الزمرد وطريق الطوب الأصفر إلى آليات تفاعلية عبر هندسة برمجيات إبداعية وتخصيص عميق.",
