  "Desenvolvimento, Inovação & Defesa Cibernética": "التطوير والابتكار والدفاع السيبراني",
  "Minha trajetória é guiada pela curiosidade e pela paixão por tecnologia e livros. Desde pequeno, gosto de explorar minha criatividade por meio da criação de mods para Minecraft, desenvolvendo personagens e transformando minhas próprias ideias em realidade, seja por meio da tecnologia ou da criação de livros. Sempre busquei aprender sobre Java e outras linguagens, e estou sempre buscando aprender algo novo.": "يقود مسيرتي الفضولُ وشغفي بالتقنية والكتب. منذ صغري أحب استكشاف إبداعي من خلال إنشاء تعديلات (mods) للعبة Minecraft، وتصميم الشخصيات، وتحويل أفكاري إلى واقع، سواء بالتقنية أو بتأليف الكتب. لطالما سعيت إلى تعلّم Java ولغات أخرى، وأبحث دائمًا عن تعلّم شيء جديد.",
  "Tenho conhecimentos em desenvolvimento web, criando interfaces modernas e responsivas com HTML, CSS, JavaScript e Bootstrap. Também venho explorando a modelagem e o desenvolvimento 3D, utilizando ferramentas como Blender, Blockbench e Unity para criar personagens, ambientes e experiências tridimensionais em meus projetos.": "لدي معرفة بتطوير الويب، وأنشئ واجهات حديثة ومتجاوبة باستخدام HTML وCSS وJavaScript وBootstrap. كما أستكشف النمذجة والتطوير ثلاثي الأبعاد باستخدام أدوات مثل Blender وBlockbench وUnity لإنشاء شخصيات وبيئات وتجارب ثلاثية الأبعاد في مشاريعي.",
  "Além disso, venho me aprofundando na área de cibersegurança, estudando análise de vulnerabilidades, redes, pentest e boas práticas de proteção digital. Também utilizo Python, Java e C# no desenvolvimento de projetos e automação, explorando diferentes formas de resolver problemas através da programação. Tenho investido bastante em cursos, certificações e projetos práticos, o que me permitiu desenvolver uma base sólida em tecnologia, segurança da informação e inteligência artificial.": "إضافة إلى ذلك، أتعمق في مجال الأمن السيبراني، فأدرس تحليل الثغرات والشبكات واختبار الاختراق وأفضل ممارسات الحماية الرقمية. كما أستخدم Python وJava وC# في تطوير المشاريع والأتمتة، مستكشفًا طرقًا مختلفة لحل المشكلات بالبرمجة. استثمرت كثيرًا في الدورات والشهادات والمشاريع العملية، مما مكّنني من بناء أساس متين في التقنية وأمن المعلومات والذكاء الاصطناعي.",
