  "Ecossistema acadêmico completo voltado para mentoria e troca de conhecimento entre estudantes e instrutores. Conta com comunicação bi-direcional em tempo real via WebSocket STOMP, autenticação robusta OAuth2 e gamificação de aprendizado.": "छात्रों और प्रशिक्षकों के बीच मेंटरशिप और ज्ञान-साझेदारी के लिए एक संपूर्ण अकादमिक इकोसिस्टम। इसमें WebSocket STOMP के ज़रिए रियल-टाइम दो-तरफ़ा संचार, मज़बूत OAuth2 ऑथेंटिकेशन और सीखने का गेमिफ़िकेशन है।",
  "Chat e sessões colaborativas de mentoria em tempo real via WebSocket e mensageria STOMP.": "WebSocket और STOMP मैसेजिंग के ज़रिए रियल-टाइम चैट और सहयोगी मेंटरशिप सत्र।",
  "Mecanismo de controle de acesso rigoroso com Spring Security, criptografia BCrypt e tokens.": "Spring Security, BCrypt एन्क्रिप्शन और टोकन के साथ सख़्त एक्सेस कंट्रोल।",
  "Gamificação dinâmica com acúmulo de pontos de transmissão, badges de conquista e ranking.": "ज्ञान साझा करने के पॉइंट, उपलब्धि बैज और रैंकिंग के साथ डायनेमिक गेमिफ़िकेशन।",
  "Exploração Anatômica & Modelagem 3D": "एनाटॉमिकल एक्सप्लोरेशन और 3D मॉडलिंग",
  "Renderização tridimensional em tempo real via WebGL com controle de câmeras e corte transversal.": "WebGL के ज़रिए रियल-टाइम 3D रेंडरिंग, कैमरा कंट्रोल और क्रॉस-सेक्शन के साथ।",
  "Sistema de anotações médicas holográficas e nós de descrição histológica interativos.": "होलोग्राफ़िक मेडिकल एनोटेशन और इंटरैक्टिव हिस्टोलॉजी विवरण नोड।",
  "Alta performance gráfica computacional com pipeline de shaders customizados GLSL.": "कस्टम GLSL शेडर पाइपलाइन के साथ उच्च ग्राफ़िक्स परफ़ॉर्मेंस।",
  "Modding Criativo & Engenharia Virtual": "क्रिएटिव मॉडिंग और वर्चुअल इंजीनियरिंग",
  "Universo fantástico inspirado no cânone de Oz, transportando elementos icônicos como a Cidade das Esmeraldas e a Estrada de Tijolos Amarelos para mecânicas interativas com engenharia de software criativa e customização profunda.": "ओज़ की कहानियों से प्रेरित एक फ़ैंटेसी दुनिया, जो एमरल्ड सिटी और येलो ब्रिक रोड जैसे प्रतिष्ठित तत्वों को रचनात्मक सॉफ़्टवेयर इंजीनियरिंग और गहरे कस्टमाइज़ेशन के साथ इंटरैक्टिव मैकेनिक्स में बदलती है।",
  "Geração procedural de estruturas e biomas mágicos inspirados na Cidade das Esmeraldas.": "एमरल्ड सिटी से प्रेरित जादुई संरचनाओं और बायोम का प्रोसीजरल जनरेशन।",
